mapper.update:
UPDATE payment_records SET refunded_amount=refunded_amount + #{amount},
  updated_at=CURRENT_TIMESTAMP(6), version=version+1 WHERE id=#{paymentId}
  AND refunded_amount + #{amount} <= amount

UPDATE payment_remote_message_inbox SET processing_status=#{status}, response_payload=#{response},
  error_detail=#{error}, processed_at=CURRENT_TIMESTAMP(6) WHERE message_id=#{id} AND
  payload_fingerprint=#{fingerprint}
